 if(p.kind==='installment')bodies={_fixtures:b[1],'':imp('_fixtures')+b[3],_harness:imp('_fixtures')+imp('')+b[6],_test:imp('_fixtures')+imp('')+[b[2],b[4],b[5],b[7]].join('\n')};
