 for(const [suffix,body]of Object.entries(bodies)){
  const assembled='module '+base+suffix+' {\n'+b[0]+body+'\n}\n'+(p.kind==='swap'&&suffix==='_test'?'':'\n');
  check(fs.readFileSync(root+'/assembled/'+base+suffix+'.qnt','utf8')===assembled,'exact-assembly:'+base+suffix);
 }
 const r=JSON.parse(fs.readFileSync(root+'/'+p.kind+'-typecheck.json'));
 check(r.planHash===p.sha256&&terminalPass(r),'terminal-typecheck:'+p.kind);
 check(r.cmd==='quint typecheck '+base+'_test.qnt','exact-command:'+p.kind);
 for(const f of r.sourceClosure){
