 }
 const noExit={...r,outputs:r.outputs.filter(x=>!Object.hasOwn(x,'exit_code'))};
 const failed={...r,outputs:r.outputs.map(x=>Object.hasOwn(x,'exit_code')?{...x,exit_code:1}:x)};
 controls.push({kind:p.kind,missingTerminalRejected:!terminalPass(noExit),failedTerminalRejected:!terminalPass(failed),changedPlanHashRejected:hash(fs.readFileSync(p.path)+' MUTATED')!==p.sha256});
